CREATE TABLE `platform_api_clients` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`name` VARCHAR(120) NOT NULL,`client_prefix` VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`secret_hash` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`scopes_json` JSON NOT NULL,`quota_per_minute` INT UNSIGNED NOT NULL,`status` ENUM('active','revoked','rotated','expired') NOT NULL,`expires_at` DATETIME(3) NOT NULL,`last_used_at` DATETIME(3) NULL,`rotated_from_id` CHAR(36) CHARACTER SET ascii NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`revoked_by` CHAR(36) CHARACTER SET ascii NULL,`revoked_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_platform_client_secret`(`secret_hash`),KEY `idx_platform_client_org_status`(`organization_id`,`status`,`expires_at`),CONSTRAINT `fk_platform_client_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_platform_client_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_platform_client_revoker` FOREIGN KEY(`revoked_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_platform_client_rotated` FOREIGN KEY(`rotated_from_id`) REFERENCES `platform_api_clients`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `open_api_request_nonces` (`client_id` CHAR(36) CHARACTER SET ascii NOT NULL,`nonce` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`request_timestamp` DATETIME(3) NOT NULL,`expires_at` DATETIME(3) NOT NULL,PRIMARY KEY(`client_id`,`nonce`),KEY `idx_open_nonce_expiry`(`expires_at`),CONSTRAINT `fk_open_nonce_client` FOREIGN KEY(`client_id`) REFERENCES `platform_api_clients`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `open_api_usage` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`client_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(160) CHARACTER SET ascii NOT NULL,`outcome` ENUM('succeeded','failed','blocked') NOT NULL,`status_code` SMALLINT UNSIGNED NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`occurred_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_open_usage_client_time`(`client_id`,`occurred_at`),KEY `idx_open_usage_org_time`(`organization_id`,`occurred_at`),KEY `idx_open_usage_trace`(`trace_id`),CONSTRAINT `fk_open_usage_client` FOREIGN KEY(`client_id`) REFERENCES `platform_api_clients`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_open_usage_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `webhook_endpoints` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`name` VARCHAR(120) NOT NULL,`target_url` VARCHAR(1000) CHARACTER SET ascii NOT NULL,`events_json` JSON NOT NULL,`secret_ciphertext` BLOB NOT NULL,`secret_nonce` BINARY(12) NOT NULL,`secret_auth_tag` BINARY(16) NOT NULL,`key_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`fingerprint` CHAR(16) CHARACTER SET ascii NOT NULL,`status` ENUM('active','disabled') NOT NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`updated_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_webhook_endpoint_org_status`(`organization_id`,`status`,`updated_at`),CONSTRAINT `fk_webhook_endpoint_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_webhook_endpoint_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_webhook_endpoint_updater` FOREIGN KEY(`updated_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `webhook_deliveries` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`endpoint_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(100) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`status` ENUM('queued','leased','succeeded','retry_scheduled','dead_letter') NOT NULL,`attempt_count` TINYINT UNSIGNED NOT NULL DEFAULT 0,`available_at` DATETIME(3) NOT NULL,`lease_owner` VARCHAR(160) CHARACTER SET ascii NULL,`lease_expires_at` DATETIME(3) NULL,`response_status` SMALLINT UNSIGNED NULL,`last_error_code` VARCHAR(80) CHARACTER SET ascii NULL,`signature_timestamp` BIGINT UNSIGNED NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_webhook_endpoint_event`(`endpoint_id`,`event_id`),KEY `idx_webhook_delivery_ready`(`status`,`available_at`,`lease_expires_at`),KEY `idx_webhook_delivery_org_time`(`organization_id`,`created_at`),CONSTRAINT `fk_webhook_delivery_endpoint` FOREIGN KEY(`endpoint_id`) REFERENCES `webhook_endpoints`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_webhook_delivery_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `webhook_delivery_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`delivery_id` CHAR(36) CHARACTER SET ascii NOT NULL,`endpoint_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`from_status` VARCHAR(40) CHARACTER SET ascii NULL,`to_status` VARCHAR(40) CHARACTER SET ascii NOT NULL,`attempt_count` TINYINT UNSIGNED NOT NULL,`reason` VARCHAR(500) NULL,`actor_id` CHAR(36) CHARACTER SET ascii NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`occurred_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_webhook_event_delivery_time`(`delivery_id`,`occurred_at`),KEY `idx_webhook_event_org_time`(`organization_id`,`occurred_at`),CONSTRAINT `fk_webhook_event_delivery` FOREIGN KEY(`delivery_id`) REFERENCES `webhook_deliveries`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_webhook_event_endpoint` FOREIGN KEY(`endpoint_id`) REFERENCES `webhook_endpoints`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_webhook_event_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_webhook_event_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `open_platform_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(180) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_open_platform_operation`(`actor_id`,`route_key`,`idempotency_key`),CONSTRAINT `fk_open_platform_operation_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
